use std::fmt::Write;
use std::str::Utf8Error;

/// Hex-encodes the given byte slice into a UTF-8 string.
///
/// Returns `Ok(String)` containing the hex-encoded representation of `input`,
/// or an error if the resulting string cannot be represented as valid UTF-8.
///
/// # Errors
///
/// This function will return `Err` if the hex-encoded string cannot be
/// represented as valid UTF-8. This is extremely unlikely in practice,
/// as hex encoding only produces ASCII characters (0-9, a-f).
///
/// # Examples
///
/// ```
/// let bytes = [0x48, 0x65, 0x6c, 0x6c, 0x6f];
/// let hex = hex_encode(&bytes).unwrap();
/// assert_eq!(hex, "48656c6c6f");
/// ```
pub fn hex_encode(input: &[u8]) -> Result<String, Utf8Error> {
    // Each byte becomes two hex characters, so the output length is exactly 2 * input.len()
    let mut result = String::with_capacity(input.len() * 2);
    for &byte in input {
        write!(result, "{:02x}", byte)?;
    }
    Ok(result)
